import React, { useEffect } from 'react';
import { useParams, Link, Navigate } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { ArrowLeft, Calendar, Clock, Linkedin, Mail, Share2 } from 'lucide-react';
import { articleContent } from '../data/articles-content';
import { profile } from '../data/portfolio';

const formatDate = (iso) => {
  try {
    const d = new Date(iso);
    return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
  } catch (e) {
    return iso;
  }
};

const Article = () => {
  const { slug } = useParams();
  const article = articleContent.find((a) => a.slug === slug);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'instant' });
  }, [slug]);

  if (!article) return <Navigate to="/writing" replace />;

  // Generate share URLs
  const articleUrl = `${window.location.origin}/#/writing/${slug}`;
  const shareText = `${article.title} by ${profile.name}`;
  
  const twitterShareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(articleUrl)}`;
  const linkedinShareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(articleUrl)}`;

  return (
    <article className="max-w-2xl mx-auto px-6 pb-16">
      <div className="pt-10 md:pt-14">
        <Link
          to="/writing"
          className="inline-flex items-center gap-2 text-[12.5px] mono uppercase tracking-widest text-ink-mute hover:text-brand transition-colors mb-10"
        >
          <ArrowLeft size={14} /> Back to writing
        </Link>
      </div>

      <header className="mb-12 fade-up">
        <div className="flex flex-wrap items-center gap-3 mono uppercase tracking-widest text-[10.5px] text-ink-mute mb-6">
          <span className="inline-flex items-center gap-1.5">
            <Calendar size={12} /> {formatDate(article.date)}
          </span>
          <span>·</span>
          <span className="inline-flex items-center gap-1.5">
            <Clock size={12} /> {article.readingTime} min read
          </span>
          {article.tags?.length > 0 && (
            <>
              <span>·</span>
              <span>{article.tags.join(' · ')}</span>
            </>
          )}
        </div>

        <h1 className="text-[28px] md:text-[36px] leading-[1.1] tracking-tight font-medium">
          {article.title}
        </h1>
        {article.subtitle && (
          <p className="mt-4 text-[18px] md:text-[19px] text-ink-soft leading-relaxed serif-italic">
            {article.subtitle}
          </p>
        )}

        <div className="mt-8 pt-6 border-t border-border/60 flex items-center gap-3 text-[13px] text-ink-soft">
          <div className="w-9 h-9 rounded-full bg-brand/20 border border-brand/40 flex items-center justify-center text-brand text-[13px] font-semibold">
            VW
          </div>
          <div className="flex-1">
            <div className="text-foreground font-medium">{profile.name}</div>
            <div className="text-[12px] text-ink-mute">{profile.role} · {profile.discipline}</div>
          </div>
          <a
            href={profile.socials.linkedin}
            target="_blank"
            rel="noreferrer"
            aria-label="LinkedIn"
            className="w-9 h-9 rounded-lg border border-border flex items-center justify-center text-ink-soft hover:text-brand hover:border-brand/50 transition-colors"
          >
            <Linkedin size={14} />
          </a>
          <a
            href={profile.socials.email}
            aria-label="Email"
            className="w-9 h-9 rounded-lg border border-border flex items-center justify-center text-ink-soft hover:text-brand hover:border-brand/50 transition-colors"
          >
            <Mail size={14} />
          </a>
        </div>
      </header>

      <div className="article-body fade-up">
        <ReactMarkdown remarkPlugins={[remarkGfm]}>{article.body}</ReactMarkdown>
      </div>

      <div className="mt-16 pt-8 border-t border-border/60">
        <div className="mono uppercase tracking-widest text-[10.5px] text-ink-mute mb-3">
          Enjoyed this piece?
        </div>
        <p className="text-[15px] text-ink-soft leading-relaxed max-w-xl">
          Follow along on{' '}
          <a href={profile.socials.linkedin} target="_blank" rel="noreferrer" className="text-brand hover:underline">
            LinkedIn
          </a>{' '}
          for new posts, or{' '}
          <a href={profile.socials.email} className="text-brand hover:underline">
            reply by email
          </a>{' '}
          — disagreements welcome.
        </p>
        
        <div className="mt-8 flex items-center gap-3">
          <a
            href={twitterShareUrl}
            target="_blank"
            rel="noreferrer"
            className="inline-flex items-center gap-2 px-4 py-2 rounded-md border border-border text-[13px] text-ink-soft hover:text-foreground hover:bg-secondary transition-colors"
          >
            <Share2 size={14} />
            Share on X
          </a>
          <a
            href={linkedinShareUrl}
            target="_blank"
            rel="noreferrer"
            className="inline-flex items-center gap-2 px-4 py-2 rounded-md border border-border text-[13px] text-ink-soft hover:text-foreground hover:bg-secondary transition-colors"
          >
            <Linkedin size={14} />
            Share on LinkedIn
          </a>
        </div>
        
        <Link
          to="/writing"
          className="mt-8 inline-flex items-center gap-2 text-[12.5px] mono uppercase tracking-widest text-ink-mute hover:text-brand transition-colors"
        >
          <ArrowLeft size={14} /> All articles
        </Link>
      </div>
    </article>
  );
};

export default Article;
